package com.nextrade.persistence.adapter; import java.util.*; public final class InMemoryRepositoryAdapter<T,ID>{private final Map<ID,T> store=new LinkedHashMap<>();public synchronized T save(ID id,T value){store.put(id,value);return value;}public synchronized Optional<T> find(ID id){return Optional.ofNullable(store.get(id));}public synchronized List<T> all(){return List.copyOf(store.values());}public synchronized void delete(ID id){store.remove(id);}public synchronized int size(){return store.size();}}
